catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    // Unlock and exit if loading or cleared
    if (isLoading || newValue === '') {
        g_form.setReadOnly('what_access_level_do_you_need', false);
        return;
    }

    // Set to Staff for Minneapolis or Snapshot
    if (newValue === 'Minneapolis Sales Docs' || newValue === 'Southwest Michigan Sales Docs') {
        g_form.setValue('what_access_level_do_you_need', 'Staff');
        g_form.setReadOnly('what_access_level_do_you_need', true);
    } 
    // Set to User for Southwest Michigan
    else if (newValue === 'Snapshot San Francisco') {
        g_form.setValue('what_access_level_do_you_need', 'User');
        g_form.setReadOnly('what_access_level_do_you_need', true);
    } 
    // Reset for any other selection
    else {
        g_form.setReadOnly('what_access_level_do_you_need', false);
        g_form.clearValue('what_access_level_do_you_need');
    }
}
